		int n = in.nextInt();

		while (n-- > 0) {
			int a = in.nextInt();
			int b = in.nextInt();
			int c = in.nextInt();

			if (a < b) {
				int t = a; a = b; b = t;
			}
			if (a < c) {
				int t = a; a = c; c = t;
			}

			out.println(a*a == b*b + c*c ? "YES" : "NO");
		}
	}

	public static void main(String[] args) {
		long start = System.currentTimeMillis();

		solve();
		out.flush();

		long end = System.currentTimeMillis();
		//trace(end-start + "ms");
		in.close();
		out.close();
	}

