	public static int LCD(int a, int b) {
		int z = Integer.min(a, b);

		for(int i = z; i >= 1; i--) {
			if(a%i == 0 && b%i == 0)
				return i;
		}
		return 1;
	}

	public static int GCD(int a, int b) {
		int c = a;
		int d = b;
		while(a != b) {
			if(a < b)
				a+=c;
			else
				b+=d;
		}
		return a;
	}
}

