	}
	static void slove(){
		double Debt = 100000;
		for(int i = 1; i <= n; i++){
			Debt = Debt*1.05;
			int r = (int)Debt%1000;
			if(r != 0){
				Debt += 1000;
				Debt -= r;
				Debt = Math.round(Debt);
			}
		}
		System.out.println((int)Debt);
	}


}

