		ans[check(lot, i, n)-1] = i;
		i++;
	    }
	    for(i=0; i<w; i++)
		System.out.println(ans[i]);
	}
    }

    int check(int[][] lot, int i, int n){
	int k = 1;
	while(k<=n){
	    //System.out.println("*"+i+" "+lot[k][i]);
	    if(lot[k][i]!=0)
		i = lot[k][i];
	    k++;
	}
	//System.out.println();
	return i;
    }
}

