    public static int bubbleSort(int[] ints){
        int result=0;
        for(int i=ints.length;i>1;i--){
            for(int j=ints.length-1;j>ints.length-i;j--){
                if(ints[j]<ints[j-1]){
                    int tmp=ints[j];
                    ints[j]=ints[j-1];
                    ints[j-1]=tmp;
                    result++;
                }
            }
        }
        return result;
    }

}

