        for (int i = 0; i < values.length; i++) {
            switch (values[i]) {
            case "+":
                stack.push(stack.pop() + stack.pop());
                break;
            case "-":
                stack.push(-(stack.pop() - stack.pop()));
                break;
            case "*":
                stack.push(Long.valueOf(stack.pop() * stack.pop()));
                break;
            default:
                stack.push(Long.parseLong(values[i]));
            }
        }

        System.out.println(stack.pop());
    }
}

