class Main
{
	static class Stack
	{
		int A[], head;
		Stack( int size )
		{
			A = new int[size+1];
			head = 0;
		}
		void show()
		{
			for( int i = 1 ; i < A.length ; i++ )
				if( i==A.length-1 )System.out.println(A[i]);
				else System.out.print(A[i]+" ");
		}
		boolean isEmpty(){return head==0;}
		boolean isFull( ){return head==A.length-1;}
		void push( int key )
		{
			if( isFull() )return;
			A[++head] = key;
		}
		int pop()
		{
			if( isEmpty() )return 0;
			return A[head--];
		}
	}
