        int[] s = nia(n);
        int q = ni();
        int[] t = nia(q);

        int ans = 0;
        for (int i = 0; i < q; i++) {
            int high = n;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                if (s[mid] > t[i]) {
                    high = mid;
                } else {
                    low = mid;
                }
