class SmallLargeOrEqual {
    private int a;
    private int b;

    SmallLargeOrEqual(int a, int b) {
        this.a = a;
        this.b = b;
    }

    @Override
    public String toString() {
        return String.format((this.a == this.b) ? "==" : ((this.a > this.b) ? ">" : "<"));
    }
}

