            }else if(n == 1){
                max = a;
                min = a;
            }else if(a < min){
                min = a;
            }else if(a > max){
                max = a;
            }else if(a == min || a == max){
                continue;
            }

        }
    System.out.println(min + " " + max + " " + sam);
    }
