class Score {
	int midterm;
	int term;
	int makeUp;

	Score(int midterm, int term, int makeUp) {
		this.midterm = midterm;
		this.term = term;
		this.makeUp = makeUp;
	}

	String getGrade() {
		int finalScore = midterm + term;
		String result;
		if (midterm == -1 || term == -1 || finalScore < 30) {
			result = "F";
		} else if (finalScore < 50) {
			if (makeUp >= 50) {
				result = "C";
			} else {
				result = "D";
			}
		}else if(finalScore < 65){
			result = "C";
		}else if(finalScore < 80){
			result = "B";
		}else{
			result = "A";
		}
		return result;
	}

	@Override
	public int hashCode() {
		final int prime = 31;
		int result = 1;
		result = prime * result + makeUp;
		result = prime * result + midterm;
		result = prime * result + term;
		return result;
	}

	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		Score other = (Score) obj;
		if (makeUp != other.makeUp)
			return false;
		if (midterm != other.midterm)
			return false;
		if (term != other.term)
			return false;
		return true;
	}

}

