import java.util.Scanner;
public class Main {
    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        int t = scan.nextInt();
        int u = scan.nextInt();
        int n = t + 1;
        int m = u + 1;
        int[][] a = new int[n][m];

        int i,r;
        for(i = 0; i < n - 1; ++i){
            for(r = 0; r < m - 1; ++r){
                a[i][r] = scan.nextInt();
                a[i][m - 1] += a[i][r];
                a[n - 1][r] += a[i][r];
                a[n - 1][m - 1] += a[i][r];
            }
        }
        for(i = 0; i < n; ++i){
            for(r = 0; r < m; ++r){
                if(r == m - 1){
                    System.out.println(a[i][r]);
                }
                else
                System.out.print(a[i][r]+" ");

            }
        }
    }
}

import java.*;
import java.util.*;

public class Main{
public static void main(String args[]){
	Scanner scan = new Scanner(System.in);
	int nrow, ncol;
	spreadsheet sp=new spreadsheet(nrow=scan.nextInt(),ncol=scan.nextInt());
	for(int i=0;i<nrow;i++)
		for(int j=0;j<ncol;j++)
			sp.load(i,j,scan.nextInt());
	sp.rowSum();
	sp.colSum();
	sp.show();
	}
}
class spreadsheet{
	int nrow;
	int ncol;
	int[][] cells;
	public spreadsheet(int r, int c){
		nrow=r;
		ncol=c;
		cells = new int[nrow+1][ncol+1];
	}
	public void load(int i, int j, int n){
		cells[i][j]=n;
	}
	public void rowSum(){
		for(int i=0; i< nrow; i++){
			int sum=0;
			for(int j=0;j<ncol;j++)
				sum+=cells[i][j];
			cells[i][ncol]=sum;
		}
	}
	public void colSum(){
		for(int j=0; j<= ncol; j++){
			int sum=0;
			for(int i=0;i<nrow;i++)
				sum+=cells[i][j];
			cells[nrow][j]=sum;
		}
	}
	public void show(){
		for(int i=0; i<= nrow; i++){
			for(int j=0;j<=ncol;j++){
				if(j==0)
				System.out.printf("%d",cells[i][j]);
				else
				System.out.printf(" %d",cells[i][j]);
			}
			System.out.printf("\n");
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int[] arr = parceIntArray(br.readLine().split(" "));
		int r = arr[0];
		int c = arr[1];
		int[][] sheet = new int[r + 1][c + 1];
		for(int i = 0;i < r;i++){
			arr = parceIntArray(br.readLine().split(" "));
			for(int j = 0;j < arr.length;j++){
				sheet[i][j] = arr[j];
			}
		}
		arr = null;
		for(int i = 0;i < r;i++){
			for(int j = 0;j < c;j++){
				sheet[i][c] += sheet[i][j];
			}
		}
		for(int i = 0;i < c + 1;i++){
			for(int j = 0;j < r;j++){
				sheet[r][i] +=  sheet[j][i];
			}
		}
		for(int i = 0;i < r + 1;i++){
			write(sheet[i]);
		}
	}

	static int[] parceIntArray(String[] strArr){
		int[] arr = new int[strArr.length];
		for(int i = 0;i < arr.length;i++){
			arr[i] = Integer.parseInt(strArr[i]);
		}
		return arr;
	}

	static void write(int[] arr){
		StringBuilder sb = new StringBuilder();
		for(int i = 0;i < arr.length;i++){
			sb.append(arr[i]);
			if(i >= arr.length - 1){
				break;
			}
			sb.append(" ");
		}
		System.out.println(sb.toString());
	}
}

