public class Main {

	static Scanner sc = new Scanner(System.in);
	public static void main(String[] args) {

		int n = sc.nextInt();
		int m = sc.nextInt();
		int l = sc.nextInt();
		int[][] A = new int[n][m];
		int[][] b = new int[m][l];
		long[][] c = new long[n][l];

		A = inputMat(A);
		b = inputMat(b);

		vec_multi(A, b, c);
		sc.close();


	}

	public static int[][] inputMat(int[][] a) {
		int[][] mat = new int[a.length][a[0].length];

		for (int i = 0; i < a.length; i++) {
			for (int j = 0; j < a[0].length; j++) {
				mat[i][j] = sc.nextInt();
			}
		}

		return mat;
	}

	public static void vec_multi(int[][] a, int[][] b, long[][] c) {

		for (int i = 0; i < c.length; i++) {
			for (int j = 0; j < c[0].length; j++) {
				for (int k = 0; k < b.length; k++) {
					c[i][j] += a[i][k] * b[k][j];
				}
			}
		}

		for (int i = 0; i < c.length; i++) {
			for (int j = 0; j < c[0].length; j++) {
				System.out.print(c[i][j]);

					if (j < c[0].length - 1) {
						System.out.print(" ");
					}
			}
			System.out.println();
		}



	}


}

public class Main {

	public void run(java.io.InputStream in, java.io.PrintStream out) {
		final java.util.Scanner sc = new java.util.Scanner(in);
		long[][] a;
		long[][] b;
		long[][] r;
		int n, m, l;

		n = sc.nextInt();
		m = sc.nextInt();
		l = sc.nextInt();
		a = new long[n][m];
		b = new long[m][l];
		for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j) {
			a[i][j] = sc.nextLong();
		}
		for (int i = 0; i < m; ++i)
		for (int j = 0; j < l; ++j){
			b[i][j] = sc.nextLong();
		}

		r = new long[n][l];
		for (int i = 0; i < n; ++i)
		for (int j = 0; j < l; ++j) {
			r[i][j] = 0;
