	 static int func(String s ,String p ,int i ,int j ,int count){
		int p_count = (i+1)%p.length();
		int s_count = (j+1)%s.length();
		int ans = 0;

		if(count == p.length()){
			ans = 1;
		}
		else if(s.charAt(s_count) == p.charAt(p_count)){
				count++;
				ans = func(s,p,p_count,s_count,count);
			}
		else{
			ans = -1;
		}

		 return ans;
	}

}

