			wordLength = sum % n.length();
			shufflesList.add(wordLength);
			sum = 0;
			count++;
		}
		for (int i = 0; i < count; i++) {
			char[] array = wordsList.get(i).toCharArray();
			int shuffle = shufflesList.get(i);
