public class Main {
    private static Scanner sc = new Scanner(System.in);
    public static void main(String[] args) throws Exception {
        while (true) {
            String s = sc.next();
            if (s.equals("-")) break;
            solve(s, sc.nextInt());
        }
    }

    private static void solve(String s, int m) {
        int c = 0;
        int l = s.length();
        for (int i = 0;i < m;i++) c += sc.nextInt();
        c %= l;
        if (c == 0) {
            System.out.println(s);
        } else {
            System.out.print(s.substring(c, l));
            System.out.print(s.substring(0, c));
            System.out.println("");
        }
    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        Main main = new Main();
        main.solv();
    }

    private void solv() {
        Scanner input = new Scanner(System.in);
        while (true) {
            char[] cs = input.next().toCharArray();
            if (cs.length == 1 && cs[0] == '-') break;
            int m = input.nextInt();
            for (int i = 0; i < m; i++) {
                int h = input.nextInt();
                char[] temp = new char[h];
                for (int j = 0; j < h; j++) {
                    temp[j] = cs[j];
                }
                for (int j = h; j < cs.length; j++) {
                    cs[j - h] = cs[j];
                }
                for (int j = cs.length - h; j < cs.length; j++) {
                    cs[j] = temp[j - (cs.length - h)];
                }
            }
            System.out.println(cs);
        }
    }
}

