class Deck{
    private String str;
    Deck(){
    }
    void setDeck(String s){
        this.str=s;
    }
    void shuffle(int h){
        this.str=this.str.substring(h,this.str.length())+this.str.substring(0,h);
    }
    void printDeck(){
        System.out.println(this.str);
    }
}

