        public void solve(InputReader in, PrintWriter out) {
            int n=in.nextInt();
            int[][] dice=new int[n][2];
            for(int i=0;i<n;i++){
                dice[i][0]=in.nextInt();
                dice[i][1]=in.nextInt();
