        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int ntc = 1;
//        ntc = in.nextInt();
            while ((ntc--) > 0) {
                out.println((1000 - (in.nextInt() % 1000)) % 1000);
            }
        }

