			tmp = h_ang - m_ang;
		}else{
			tmp = m_ang - h_ang;
		}
		if(tmp>180){
			tmp-=360;
		}
		double cos = Math.cos(Math.toRadians(tmp));
		double result = (a*a) + (b*b) - (2*a*b*cos);
		System.out.println(Math.sqrt(result));
	}
}

