            if (a > 0) {
                if (a >= k) ans += k;
                else ans += a;
                tmp -= a;
                a = a - k;
                k = tmp;
            }
            if (a <= 0 && b > 0 && k > 0) {
                tmp -= b;
                b = b - k;
                k = tmp;
            }
            if (a <= 0 && b <= 0 && c > 0 && k > 0) {
                ans -= k;
            }

            // 出力
            out.println(ans);

        }

    }
