//	Aから順に、合計K枚になるまで足していく
		if(A >= K) {  //A>KならKの枚数を表示で終了
			System.out.println(total=K);
			return;
		}
		else {  //A＜Kの場合は続く
			total = A;
		}

//	BがK-Aより多いか少ないかで判断
		if(B < K-A) {  //B<=K-AならK-A-B枚分-1をする
