    static class EasyLinearProgramming {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int c = in.nextInt();
            int k = in.nextInt();

            int result = 0;
            if (a > 0) {
                int min = Math.min(a, k);
                k -= min;
                result += min;
            }
            if (b > 0) {
                int min = Math.min(b, k);
                k -= min;
            }
            if (c > 0) {
                int min = Math.min(c, k);
                k -= min;
                result -= min;
            }
            out.append(String.valueOf(result));
        }

    }
}

