	private static void solve(){
		//Implement solution here.
		int N = ni();
		int M = ni();		
		int[] A = na(M);

		Arrays.sort(A);
		int idx = 0;		
		while(idx < M) {
			if(N - A[idx] >= 0) {
				N -= A[idx];
				idx++;
			} else {
