	public static int[] getProcess(int N, int[] A){
		int[] ret = new int[N];
		for(int i=0; i<ret.length; i++){
			ret[i] = 0;
		}

		for(int i=0; i<A.length; i++){
			if(A[i]==0){
				continue;
			}
			ret[ A[i]-1 ] ++;
		}

		return ret;
	}


}

