		PrintWriter out = new PrintWriter(outputStream);
		new Solution().solve(in, out);
		out.close();
	}

	private static class Solution {
		private void solve(InputReader in, PrintWriter out) {
			int k = in.nextInt();
			long ans = 0;
			for (int a = 1; a <= k; ++a)
				for (int b = 1; b <= k; ++b)
					for (int c = 1; c <= k; ++c)
						ans += gcd(gcd(a, b), c);
			out.println(ans);
		}

		private long gcd(long a, long b) {
			while (b != 0) {
				long m = a % b;
				a = b;
				b = m;
			}
			return a;
		}
	}


