        for(int i=1 ; i<=k ; i++){
            for(int j=i+1 ; j<=k ; j++){
                long calc = (long) gcd(i,j)*6;
                ans += calc;
            }
        }

        for(int i=1 ; i<=k ; i++){
            for(int j=i+1 ; j<=k ; j++){
                for(int l=j+1 ; l<=k ; l++){
                    int calc = gcd(i,j);
                    long calcF = gcd(calc,l);
                    ans += calcF*6;
                }
            }
        }
        out.println(ans);



        out.close();
    }
