        a = sort(a);
        if(a[m-1] >= aa/(4.0*m)){
            System.out.println("Yes");          
        }else{
            System.out.println("No");
        }
    }
    public static int[] sort(int[] a){
        int x;
        for(int i=0;i<a.length;i++){
            x = a[i];
            for(int j=0;j<a.length;j++){
                if(x == Math.max(x,a[j])){
                    a[i]=a[j];
                    a[j]=x;
                    x=a[i];
                }
            }
        }
        return a;
    }
}

