        // 初期値
        long n = sc.nextLong();
        // x を x と K の差の絶対値
        long k = sc.nextLong();

        long remainder = n % k;

        if( k - remainder > remainder ) {
            System.out.println( remainder );
        }
        else {
            System.out.println( k - remainder );
        }

        sc.close();
    }
}

