public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 入力
        int k = sc.nextInt();
        int n = sc.nextInt();

        int[] a = new int[n];
        for(int i = 0; i < n; i++){
            a[i] = sc.nextInt();
        }

        // 処理
        int out = k;

        //時計回り
        int work = 0;
        for(int i = 0; i < n; i++){
            int dist = a[(i + 1 + n) % n] - a[i];
            if (dist < 0) {
                dist += k;
            }
            work = dist > work ? dist : work;
        }
        out = k - work;

        // 出力
        System.out.println(out);
    }
}

