public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		char[] S = sc.next().toCharArray();
		sc.close();
		boolean ok = true;
		int N = S.length;
		// Sは回文であるか
		for(int i = 0; i < N; i++) {
			ok &= S[i] == S[N - i - 1];
		}
		// Sの1文字目から(N - 1)/2文字目まで(両端含む)からなる文字は回文であるか
		for(int i = 0; i < (N - 1) / 2; i++) {
			ok &= S[i] == S[(N - 1) / 2 - i - 1];
		}
		// Sの(N + 3)/2文字目からN文字目まで(両端含む)からなる文字は回文であるか
		// ※Sが回分であることが条件のため、Sの(N + 3)/2文字目移行の文字と1文字目～からが回分であればOK
		for(int i = (N + 3) / 2 - 1; i < N; i++) {
			ok &= S[i] == S[N - i - 1];
		}
		System.out.println(ok ? "Yes" : "No");
	}
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    String s;
    char[] ch;
    char[] ch1;
    char[] ch2;

    public void run() {
        // 入力情報取得
        Scanner sc = new Scanner(System.in);
        s = sc.next();
        ch = s.toCharArray();
        sc.close();

        // 解答処理
        solve();
    }

    private void solve() {
        int n = ch.length;
        boolean c1 = true;
        boolean c2 = true;
        boolean c3 = true;

        ch1 = new char[(n - 1) / 2];
        ch2 = new char[(n - 1) / 2];
        for (int i = 0; i < (n - 1) / 2; i++) {
            ch1[i] = ch[i];
        }
        for (int i = 0; i <= n - (n + 3) / 2; i++) {
            ch2[i] = ch[i - 1 + ((n + 3) / 2)];
        }
        c1 = check(ch);
        c2 = check(ch1);
        c3 = check(ch2);
        if (c1 && c2 && c3) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    private boolean check(char[] target) {
        boolean res = true;
        for (int i = 0; i < target.length / 2; i++) {
            if (target[i] != target[target.length - i - 1]) {
                res = false;
            }
        }
        return res;
    }
}

