        long ballCnt = 0;

        // 繰り返す数を求める
        long divisionAns = n / ( a + b );
        // 繰り返す数を算出した割り算の余りを求める
        long remainderOfDivision = n % ( a + b );

        ballCnt += divisionAns * a;
        ballCnt += remainderOfDivision < a ? remainderOfDivision : a;

        System.out.println( ballCnt );

        sc.close();
    }
}

