		long countBlue = num/(blue+red)*blue;  //上記の際の青の数

		if(remainder >= blue) {  //余りが青の数よりも多い場合
			countBlue += blue;  //全ての青の数を足す
		}
		else {                      //余りが青よりも少ない場合
			countBlue += remainder;  //余りの分だけ青を足す
		}
		System.out.print(countBlue);
		sc.close();
	}
}

