        // 判定
        double exponentCount = 1;

        while (true) {
            double exponentNum = Math.pow(baseNum, exponentCount);
            if (checkNum < exponentNum) {
                break;
            }
            exponentCount++;
        }

        long count = (long)exponentCount;

        System.out.println(count);

    }

}

