    void solve() throws IOException {
        int n = sc.nextInt();
        int[] x = new int[n];
        for(int i=0;i<n;i++) x[i] = sc.nextInt();
        long mini = Long.MAX_VALUE/2;
        for(int i=0;i<=100;i++){
            long cur = helper(x,i);
            mini = Math.min(mini,cur);
        }
        System.out.println(mini);
    }
    long helper(int[] x, int guess){
        long ans = 0;
        for(int s:x){
            long diff = s-guess;
            ans += diff*diff;
        }
        return ans;
    }
}

