class Solver {
    public void solve(long N, long[] X) {
        long min = Long.MAX_VALUE;
        for (int i = 0; i < 100; i++) {
            long sum = 0;
            for (int j = 0; j < N; j++) {
                sum += Math.pow(X[j] - i, 2);
            }

            min = Math.min(min, sum);
        }
        System.out.println(min);
    }
}


