public class Main {
  private static List<String> solve(int n, String[] ss) {
    Map<String, Integer> map = new HashMap<>();
    for (String s : ss) {
      map.put(s, map.getOrDefault(s, 0) + 1);
    }
    int maxCount = 0;
    for (int count : map.values()) {
      maxCount = Math.max(maxCount, count);
    }
