            Map<String, Integer> map = new TreeMap<>();
            int max = 0;
            for (int i = 0; i < N; i++) {
                String S = in.next();
                Integer val = map.get(S);
                if (val == null) {
                    map.put(S, 1);
                    if (max <= 1) {
                        max = 1;
                    }
                }
                else {
                    map.put(S, val + 1);
                    if (max <= val + 1) {
                        max = val + 1;
                    }
                }
            }
            for (String key : map.keySet()) {
                if (map.get(key) == max) {
                    out.println(key);
                }
            }
        }
    }
