                String s = in.next();
                if (b[p - 1]) { // AC
                    continue;
                }
                if (s.equals("WA")) {
                    wCount[p - 1]++;
                } else {
                    b[p - 1] = true;
                    ac++;
                }
            }
            int totalWa = 0;
            for (int i = 0; i < n; i++) {
                if (b[i]) {
                    totalWa += wCount[i];
                }
            }
            out.println(ac + " " + totalWa);
        }

    }
