    public static boolean isPrime(int n) {
        if (n == 1)
            return false;
        if (n == 2)
            return true;
        if (n % 2 == 0)
            return false;
        // n>=3,奇数
        int max = (int) Math.sqrt(n);
        for (int i = 3; i < max + 1; i += 2) {
            if (n % i == 0)
                return false;
        }
        return true;
    }

