	public static void main(String[] args) {

		int A = in.nextInt();
		int B = in.nextInt();

		System.out.println(work(A,B));

	}

	static long work (int a, int b) {
		int temp;
		long c = a;
		c *= b;
		while((temp = a%b)!=0) {
			a = b;
			b = temp;
		}
		return (long)(c/b);
	}

