  		  a = b;
  		  b = tmp;				  
  	  }

  	  r = a % b;
  	  while(r!=0) {
  		  a=b;
  		  b=r;
  		  r=a%b;
  	  }

  	  return b;
    }

    static long LCM(long a,long b) {
  	  return a*b/GCD(a,b);
    }
}

