	  private static long getKoyakusu(long a, long b) {
	    long candidate = a;
	    while (b % a != 0) {
	      candidate = b % a;
	      b = a;
	      a = candidate;
	    }
	    return candidate;
	  }

	  // 公倍数の取得
	  private static long getKobaisu(long a, long b) {
	    return (a * b) / getKoyakusu(a, b);
	  }
}

