		int k = 1;
		int sum = 0;
		for (int j = 0; j < N; j++) {
			if (t[j] == k) {
				sum++;
				k++;
			}
		}

		int res = N - sum;
		if (sum == 0) {
			res = -1;
		}

		return res;
	}
}

