class RollerCoaster {

    int[] h;
    int N;
    int K;

    public RollerCoaster(int N, int K){
        this.N = N;
        this.K = K;
        h = new int[N];
    }

    public int count() {

        int res = 0;

        Arrays.sort(h);

        int left = -1;
        int right = N;

        while(right - left > 1){

            int mid = (left + right) / 2;
            if (isOK(mid)) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return N - right;
    }

    private boolean isOK(int i){
        return h[i] >= K;
    }

}

import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import java.lang.Math;

public class Main {
    public static void main(String[] args) {
        FS reader = new FS();
        // write reader
        int mennum = reader.nextInt();
        int tallnum = reader.nextInt();
		int [] mentalls = new int[mennum];
		int cnt = 0;
        for(int i = 0; i < mennum;i++) {
        	mentalls[i] = reader.nextInt();
        	if(mentalls[i] >= tallnum) {
        		cnt++;
        	}
        }
        System.out.println(cnt);
    }

    // Read Class
    static class FS {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() { return hasNextByte() ? buffer[ptr++] : -1;}
        private boolean isPrintableChar(int c) {return 33 <= c && c <= 126;}
        private void skipUnprintable() {while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}

        public boolean hasNext() { skipUnprintable(); return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public int nextInt() {
            return (int)nextLong();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while(true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if(b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
    }
}

