        int [] count = new int[n];
        for (int i = 0; i < q; i++) {
            int ans = in.nextInt();
            count[ans - 1]++;
        }
        for (int i = 0; i < a.length; i++) {
            int correct = count[i];
            a[i] = a[i] - (q-correct);
        }
        for (int i = 0; i < a.length; i++) {
            if(a[i]>0) {
                out.println("Yes");
            }
            else {
                out.println("No");
            }
        }
        out.flush();
    }

    private static void permute(int [] a, int l, int r) {
        if(l == r) {
            List<Integer> list = new ArrayList<>();
            for(int i : a) list.add(i);
            permutations.add(list);
        }
        else {
            for (int i = l; i <=r; i++) {
                swap(a,l,i);
                permute(a,l+1,r);
                swap(a,l,i);
            }
        }
    }
    private static void swap(int [] a, int l, int r) {
        int temp = a[l];
        a[l] = a[r];
        a[r] = temp;
    }

}
