    public void go() throws IOException
    {
        ntok();
        int n = ipar();
        int[] arr = new int[n];
        ntok();
        for (int i = 0; i < n; i++)
        {
            arr[i] = ipar();
        }
        int prev = arr[0];
        int count = 1;
        int best = 1;
        for (int i = 1; i < n; i++)
        {
            if (arr[i] > prev)
            {
                count = 1;
            }
            else
            {
                count++;
            }
            best = Math.max(count, best);
            prev = arr[i];
        }
        out.println(best-1);

        out.flush();
        in.close();
