        sb.append(chars[j]);
      }
      s[i] = sb.toString();
    }
    Arrays.sort(s);

    long count = 1;
    long sum = 0;
    for (int i = 1; i < N; i++) {
      if (s[i].equals(s[i-1])) {
        count++;
        if (i == N-1) {
          sum += count * (count - 1);
        }
      } else {
        if (count == 1) {
          continue;
        } else {
          sum += count * (count - 1);
          count = 1;
        }
      }
    }

    System.out.println(sum / 2);
  }
}

