		// N - 1個のリンゴを材料としてできるアップルパイの「味」との差
		int min = Integer.MAX_VALUE;
		int r = sum;
		for(int i = 1; i <= N; i++) {
			int apple =  L + i - 1;
			int abs = Math.abs(apple);
			// System.out.println("apple = " + apple + " : " +  (sum - apple));
			if(abs < min) {
				min = abs;
				r = sum - apple;
			}
		}
		// System.out.println("min = " + min);
		System.out.println(r);
	}
}

