		long lcm = (C * D) / gcd;
		// System.out.println("gcd=" + gcd + " lcm=" + lcm);

		// B以下のCまたはDで割り切れる個数からCとDで割り切れる重複個数を引く
		// B以下の割り切れる個数を求める
		long bCnt = (B / C) + (B / D) - (B / lcm);

		// A未満のCまたはDで割り切れる個数からCとDで割り切れる重複個数を引く
		// A未満の割り切れる個数が求められる
		long a = A - 1;
		long aCnt = (a / C) + (a / D) - (a / lcm);
