  public static long gcdiv(long a, long b) {
    while (a != b) {
      if (a > b) {
        a -= b * (a / b);
        if (a == 0) {
          a = b;
        }
      } else if (b > a) {
        b -= a * (b / a);
        if (b == 0) {
          b = a;
        }
      }
    }
    return a;
  }
  public static long lcmul(long a, long b) {
    long gcdiv = gcdiv(a, b);
    a /= gcdiv;
    b /= gcdiv;
    return a * b * gcdiv;
  }
  public static long lcmul(long a, long b, long gcdiv) {
    a /= gcdiv;
    b /= gcdiv;
    return a * b * gcdiv;
  }
}

