	public static long calc(long a, long b, long c){
		long total=0;
		long mod = (a%c);
		if(mod!=0)
			mod=c-mod;
		if(a+mod<=b){
			a+=mod;
			total++;
		}
		long diff = (b-a)/c;
		total+=diff;
		return total;
	}

