class AtCoder {

    final int P, Q, R;

    AtCoder(FastScanner sc) {
        P = sc.nextInt();
        Q = sc.nextInt();
        R = sc.nextInt();
    }

    void solve(PrintWriter out) {
        if (Math.max(Math.max(P, Q),R) == P) {
            out.println(Q + R);
        } else if (Math.max(Math.max(P, Q),R) == Q) {
            out.println(P + R);
        } else {
            out.println(P + Q);
        }
    }

}

