        dp[0] = 1;
        int index = 0;
        for(int i = 0; i < N+1; i++) {
            //index s.t. a[index] >= i
            while(index < M && a[index] < i) index++;
            if(index < M && i == a[index]) continue;
            dp[i+1] += dp[i];
            dp[i+1] %= MOD;
            dp[i+2] += dp[i];
            dp[i+2] %= MOD;
        }
