			v[i] = stdIn.nextInt();
		}
		for(int i = 0; i < n; i++) {			
			c[i] = stdIn.nextInt();
		}

		int max = Integer.MIN_VALUE;

		for(int bit = 0; bit < (1 << n); bit++) {
			int sum = 0;

			for(int i = 0; i < n; i++) {
				if(((bit >> i) & 1) ==1) {
					sum+= v[i]-c[i];
				}
