            int le = sc.nextInt(), ri = sc.nextInt();
            int ans = dp[ri]-dp[le-1];
            if(le>1&&s[le]=='C'&&s[le-1]=='A') ans--;
            out.println(ans);
        }
        out.flush();
    }
}

