		int[] accum = new int[N];
		boolean flag = false;
		if(S.charAt(0) == 'A') flag = true;

		for(int i=1;i<N;i++) {
			if(S.charAt(i) == 'A') {
				flag = true;
				accum[i] = accum[i-1];
			}else if(S.charAt(i) == 'C') {
				if(flag) {
					flag = false;
					accum[i] = accum[i-1] + 1;
				}else {
					accum[i] = accum[i-1];
				}
			}else {
				if(flag) flag = false;
				accum[i] = accum[i-1];
			}
		}

		int[] ans = new int[Q];
