import java.util.*;


public class Main {
    int N,M,C;
    int[] B;
    int[][] A;
    private void solve() {
        N = nextInt();
        M = nextInt();
        C = nextInt();
        B = new int[M];
        A = new int[N][M];
        for(int i = 0;i < M;i++) {
            B[i]  = nextInt();
        }

        for(int i = 0;i < N;i++) {
            for(int j = 0;j < M;j++) {
                A[i][j] = nextInt();
            }
        }

        int ans = 0;
        for(int i = 0;i < N;i++) {
            int sum = C;
            for(int j = 0;j < M;j++) {
                sum += A[i][j] * B[j];
            }
            if (sum > 0) {
                ans++;
            }
        }

        out.println(ans);
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[4096];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

