	static int getGcd(int a, int b) {
		if (a == 0) {
			return b;
		}
		return getGcd(b % a, a);
	}
	static int getKth(int n, int k) {
		ArrayList<Integer> divisors = new ArrayList<>();
		for(int i = 1; i <= n / 2; i++){
			if(n % i == 0){
				divisors.add(i);
			}
		}
		divisors.add(n);
		return(divisors.get(divisors.size() - k));
	}
}

