    public static int eukleides(int a, int b){
        if(b % a == 0){
            return a;
        }
        int mod = b % a;

        return eukleides(mod, a);
    }

    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);

        // input
        int a = scan.nextInt();
        int b = scan.nextInt();
        int border = scan.nextInt();

        // search
