        int min = Integer.MAX_VALUE;
        for (int num : nums) {
            min = num < min ? num : min;
        }
        Main.total += min;
        int ti = 0;
        int i;
        for (i = 0; i < nums.length; i++) {
            nums[i] -= min;
            if (nums[i] == 0) {
                if (ti < i) {
                    me(Arrays.copyOfRange(nums, ti, i));
                }
                ti = i + 1;
            }
        }
        if (ti < i) {
            me(Arrays.copyOfRange(nums, ti, i));
        }
    }
}

