    }

    static class ABC116_C {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int h[] = new int[n];
            int ans = 0;
            int max = 0;
            for (int i = 0; i < n; i++) {
                h[i] = in.nextInt();
                max = Math.max(max, h[i]);
            }
            int startIndex = 0;
            int endIndex = h.length - 1;
