                if (h[i] != 0) {
                    endIndex = i;
                    break;
                }
            }
            boolean repeatingZero = false;
            while (max > 0) {
                for (int i = startIndex; i <= endIndex; i++) {
                    if (h[i] == 0 && !repeatingZero) {
                        ans++;
                        repeatingZero = true;
                    }

