                byte c = read(); 
                while (c <= ' ') c = read(); 
                boolean neg = (c == '-'); 
                if (neg) 
                    c = read(); 
                do { 
                    ret = ret * 10 + c - '0'; 
                } 
                while ((c = read()) >= '0' && c <= '9'); 
                if (neg) 
                    return -ret; 
                return ret;
            } catch (Exception e) {
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        public double nextDouble()  { 

            try {
                double ret = 0, div = 1; 
                byte c = read(); 
                while (c <= ' ') 
                    c = read(); 
                boolean neg = (c == '-'); 
                if (neg) c = read(); 

                do { 
                    ret = ret * 10 + c - '0'; 
                } 
                while ((c = read()) >= '0' && c <= '9'); 
                if (c == '.') { 
                    while ((c = read()) >= '0' && c <= '9') { 
                        ret += (c - '0') / (div *= 10); 
                    } 
                } 

                if (neg) return -ret; 
                return ret;
            } catch (Exception e) {
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        private void fillBuffer() throws IOException{ 
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE); 
            if (bytesRead == -1) 
                buffer[0] = -1; 
        } 

        private byte read() throws IOException  { 
            try{
                if (bufferPointer == bytesRead) 
                    fillBuffer(); 
                return buffer[bufferPointer++]; 
            }catch(Exception e){
                System.out.println(e.getMessage());
                return -1;
            }
        } 

        public void close() throws IOException { 
            if (din == null) 
                return; 
            din.close(); 
        } 
    } 


