public class Main {
	private static void solve(){
		//Implement solution here.
		int n = ni();
		int tlim = ni();
		int minc = Integer.MAX_VALUE;
		for(int i = 0; i < n ; i++) {
			int c = ni();
			int t = ni();
			if(t > tlim) {
				continue;
			}else {
				minc = Math.min(minc, c);
			}
		}
		if(minc == Integer.MAX_VALUE) {
			System.out.println("TLE");
		}else {
			System.out.println(minc);
		}
	}

	private static int dfs(int dig, int cur, int max) {
		int result = 0;	
		if(dig >= 3) {
			if(dig <= Integer.toString(max).length()) {
				if(cur <= max) {
					if(is753(cur))result++;
				} else {
					return 0;
				}
			} else {
				return 0;
			}
		}	
		dig++;
		result += dfs(dig, cur * 10 + 3, max) + dfs(dig, cur * 10 + 5, max) + dfs(dig, cur * 10 + 7, max);
		return result;
	}

	private static boolean is753(int in) {
		boolean[] flags = new boolean[3];
		char[] inca = Integer.toString(in).toCharArray();
		for(char c:inca) {
			if(c == '3')flags[0] = true;
			if(c == '5')flags[1] = true;
			if(c == '7')flags[2] = true;
		}

		return flags[0] && flags[1] && flags[2];
	}
