                ct[i][1] = Integer.parseInt(in.next());
            }
            int ans = Integer.MAX_VALUE;
            int tle = 0;

            for (int i = 0; i < N; i++) {
                if (ct[i][1] <= T) {
                    ans = Math.min(ans, ct[i][0]);
