    for (int i = 1; i < s.length; i++) {
      if (i >= 2 && i <= s.length - 2 && s[i] == 'C') {
        numC++;
        continue;
      }
      if (s[i] < 'a' || s[i] > 'z') {
        return false;
      }
    }
    return numC == 1;
  }
}

