    if (C <= B && B <= A) {
      for (int i = 0; i < K; i++) {
        A = A * 2;
      }
    } else if (C <= B && A <= B) {
      for (int i = 0; i < K; i++) {
        B = B * 2;
      }
    } else {
      for (int i = 0; i < K; i++) {
        C = C * 2;
      }
    }

    System.out.println(A + B + C);

  }

}

