		public void run(InputScanner in, PrintWriter out) {

			int A = in.nextInt();
			int B = in.nextInt();
			int C = in.nextInt();
			int X = in.nextInt();
			int Y = in.nextInt();

			int ans = 0;

			if (A + B > 2 * C) {
				int ab = Math.min(X, Y);
				ans += ab * 2 * C;
				X -= ab;
				Y -= ab;
			}

			if (X > 0 && A > 2 * C) {
				ans += X * 2 * C;
			} else if (X > 0){
				ans += X * A;
			}
			if (Y > 0 && B > 2 * C) {
				ans += Y * 2 * C;
			} else if (Y > 0){
				ans += Y * B;
			}

			out.println(ans);
		}
	}

