	public static boolean isPalindromicStr(String s){
		int h=0;
		int t=s.length()-1;
		while(h<=t){
			if(s.charAt(h)!=s.charAt(t)){
				break;
			}
			h++;
			t--;
		}
		if(h>t){
			return true;
		}
		return false;
	}

	public static void check() throws Exception{
		if(in == null){
			in = new BufferedReader(new InputStreamReader(System.in));
