            System.out.println("No");
        } else {
            System.out.println("Yes");
        }

    }

    private boolean check(int sa1, int sa2, int sa3) {
        return (sa1 == sa2) && (sa2 == sa3) && (sa3 == sa1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
        sc.close();
    }
}

