        }
        if(!good)
            System.out.println("No");
        else {
            // row
            for(int i = 2; i < 3; ++i){
                int diff1 = grid[0][i] - grid[0][i-1];
                int diff2 = grid[1][i] - grid[1][i-1];
                int diff3 = grid[2][i] - grid[2][i-1];
                if(diff1 != diff2 || diff2 != diff3){
                    good = false;
                    break;
                }
            }
            if(good)
                System.out.println("Yes");
            else
                System.out.println("No");
        }
    }
}

