		int[] a = new int[3];
		int[] b = new int[3];

		String ans = "No";
		LOOP: for (a[0] = 0; a[0] <= 100; a[0]++) {
			b[0] = c[0][0] - a[0];
			b[1] = c[0][1] - a[0];
			b[2] = c[0][2] - a[0];
