    private static int problem087b(int a, int b, int c, int x) {
        int count = 0;
        for (int ai = a; ai >= 0; ai--) {
            for (int bi = b; bi >=0; bi--) {
                for (int ci = c; ci >= 0; ci--) {
                    int price = ai * 500 + bi * 100 + ci * 50;
                    if (price == x) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

