    }
    for(int i=0; i<N; i++){
      A[1][i] = sc.nextInt();
      Atwo[i+1] = Atwo[i] + A[1][i];
    }
    int ans = 0;
    int tmp;
    for(int i=1; i<N+1; i++){
      tmp = Aone[i] + Atwo[N] - Atwo[i-1];
      ans = Math.max(ans, tmp);
    }
    out.println(ans);
  }

  public static int gcd(int a, int b){
    if(b == 0) return a;
    return gcd(b, a%b);
  }
