class Solver {
  private static final int[] OPS = new int[]{1, -1};

  final char[] abcd;
  int[] ops;

  Solver(char[] abcd) {
    this.abcd = abcd;
  }

  private boolean dfs(int sum, int index) {
    if (index == 3) {
      return sum == 7;
    }
    for (int op : OPS) {
      ops[index] = op;
      if (dfs(sum + op * (abcd[index + 1] - '0'), index + 1)) {
        return true;
      }
    }
    return false;
  }

  public String solve() {
    ops = new int[3];
    dfs(abcd[0] - '0', 0);

    StringBuffer sb = new StringBuffer();
    sb.append(abcd[0]);
    for (int i = 0; i < 3; i++) {
      if (ops[i] == 1) {
        sb.append('+');
      } else {
        sb.append('-');
      }
      sb.append(abcd[i + 1]);
    }
    sb.append("=7");
    return sb.toString();
  }
}

