		int[] A = new int[N];
		for (int i = 0; i < N; i++) {
			A[i] = sc.nextInt() - 1;
		}

		BitSet touched = new BitSet(N);
		int i = A[0];
		int result = 0;
		while (i != 1){
			if (touched.get(i)) {
				System.out.println(-1);
				return;
			}

			touched.set(i);
			result++;
			i = A[i];
		}
		System.out.println(result + 1);
	}
}

