		TreeSet<Long> result = new TreeSet<>();

		for (long i = 1; i * i <= n; i++) {
			if (n % i == 0) {
				result.add(i);
				result.add(n / i);
			}
		}

		return result;
	}

	private int keta(long x) {
		if (x == 0) {
			return 1;
		}
		int keta = 1;
		while (x >= 10) {
			x /= 10;
			keta++;
		}
		return keta;
	}

	private int F(long a, long b) {
		return Math.max(keta(a), keta(b));
	}

