        Scanner sc = new Scanner(System.in);
        char[] array = sc.next().toCharArray();
        StringBuilder str = new StringBuilder();

        int firstA = -1;
        int lastZ = -1;

        for(int i=0; i<array.length; i++){
            String s = String.valueOf(array[i]);
            if(s.equals("A") && firstA == -1) firstA = i;
            if(s.equals("Z")) lastZ = i;
        }

        for(int i=firstA; i<=lastZ; i++){
            str.append(String.valueOf(array[i]));
        }

        System.out.println(str.length());
    }

    double manhattan(Ten point1, Ten point2){
        return Math.abs(point1.getX() - point2.getX()) + Math.abs(point1.getY() - point2.getY());
    }

    void substring(String s, int num){
        for(int i=1; i<=num; i++){
            if(i > K){
                break;
            }
            for(int j=0; j<num; j++){
                if(j + i-1 < num){
//                    System.out.println(s.substring(j, j+i));
                    set.add(s.substring(j, j+i));
                } else {
                    break;
                }
            }
        }
    }

    void permutation(String s, String ans){
        if(s.length() <= 1){
            System.out.println(ans + s);
        } else {
            for(int i=0; i<s.length(); i++){
                permutation(s.substring(0, i) + s.substring(i + 1), ans + s.charAt(i));
            }
        }
    }
