			for (int j = i + 1; j < s.length; j++) {
				if (s[imin].compareTo(s[j]) > 0) {
					imin = j;
				}
			}
			if (imin != i) {
				exchange(s, imin, i);
			}
		}

		String sum = "";
		for (String str : s) {
			sum += str;
		}

		System.out.println(sum);
	}

	public static void exchange(String[] s, int a, int b) {
		String str = s[a];
		s[a] = s[b];
		s[b] = str;
	}

}

